#pragma once
// Folder-name rules run only on explicit import/application, never in playback or browser paint.
struct ImportRule {juce::String contains,ancestor,tags;int type=4;bool enabled=true;};
struct ImportRules {
 static std::vector<ImportRule> read(){auto value=LibraryStore::read("settings.json").getProperty("importRules",{});std::vector<ImportRule> rows;if(auto* list=value.getArray()){for(auto& r:*list)rows.push_back({r.getProperty("contains",{}).toString(),r.getProperty("ancestor",{}).toString(),r.getProperty("tags",{}).toString(),(int)r.getProperty("type",4),(bool)r.getProperty("enabled",true)});}else rows={{"bass loop",{},"bass",4,true},{"bass","loop","bass",4,true}};return rows;}
 static void save(const std::vector<ImportRule>& rows){juce::Array<juce::var> list;for(auto& row:rows){auto* o=new juce::DynamicObject();o->setProperty("contains",row.contains);o->setProperty("ancestor",row.ancestor);o->setProperty("tags",row.tags);o->setProperty("type",row.type);o->setProperty("enabled",row.enabled);list.add(juce::var(o));}LibraryStore::update("settings.json",[&](auto& o){o.setProperty("importRules",list);});}
 static bool matches(const ImportRule& r,juce::File file,juce::File root){if(!r.enabled||r.contains.trim().isEmpty())return false;for(auto folder=file.getParentDirectory();folder==root||folder.isAChildOf(root);folder=folder.getParentDirectory()){if(folder.getFileName().containsIgnoreCase(r.contains.trim())){if(r.ancestor.trim().isEmpty())return true;for(auto parent=folder.getParentDirectory();parent==root||parent.isAChildOf(root);parent=parent.getParentDirectory()){if(parent.getFileName().containsIgnoreCase(r.ancestor.trim()))return true;if(parent==root)break;}}if(folder==root)break;}return false;}
 static int apply(juce::File root,const std::vector<ImportRule>& rules){std::map<juce::String,juce::String> tags;std::map<juce::String,int> types;for(auto entry:juce::RangedDirectoryIterator(root,true,"*",juce::File::findFiles)){auto f=entry.getFile();if(f.isHidden()||!f.hasFileExtension("wav;aif;aiff;flac;mp3;ogg;mp4;m4a")||!LibraryStore::editable(f))continue;for(auto& r:rules)if(matches(r,f,root)){auto key=f.getFullPathName();if(r.tags.trim().isNotEmpty())tags[key]+=(tags[key].isEmpty()?"":",")+r.tags;if(r.type>=0)types[key]=r.type;}}
  if(!tags.empty())LibraryStore::update("tags.json",[&](auto& o){for(auto& entry:tags){auto existing=o.getProperty(entry.first).toString();auto all=juce::StringArray::fromTokens(existing+","+entry.second,",",{});all.trim();all.removeEmptyStrings();all.removeDuplicates(true);o.setProperty(entry.first,all.joinIntoString(", "));}});
  if(!types.empty())LibraryStore::update("playback-types.json",[&](auto& o){for(auto& entry:types)o.setProperty(entry.first,entry.second);});std::set<juce::String> changed;for(auto& e:tags)changed.insert(e.first);for(auto& e:types)changed.insert(e.first);return (int)changed.size();
 }
};
class ImportRulesPanel:public juce::Component {
 struct Row{juce::ToggleButton enabled;juce::TextEditor contains,ancestor,tags;juce::ComboBox type;juce::TextButton remove{"×"};};std::vector<std::unique_ptr<Row>> rows;juce::TextButton add{"ADD RULE"},save{"SAVE RULES"},apply{"SAVE + APPLY TO LIBRARIES"};juce::Label hint;
public:std::function<void()> applyExisting;ImportRulesPanel(){for(auto* c:std::vector<juce::Component*>{&add,&save,&apply,&hint})addAndMakeVisible(c);hint.setText("Folder contains | ancestor contains (optional) | tags | playback type",juce::dontSendNotification);for(auto rule:ImportRules::read())append(rule);add.onClick=[this]{append({});resized();};save.onClick=[this]{persist();};apply.onClick=[this]{persist();if(applyExisting)applyExisting();};setSize(760,400);}
 void append(ImportRule rule){auto row=std::make_unique<Row>();auto* ptr=row.get();for(auto* c:std::vector<juce::Component*>{&row->enabled,&row->contains,&row->ancestor,&row->tags,&row->type,&row->remove})addAndMakeVisible(c);row->enabled.setToggleState(rule.enabled,juce::dontSendNotification);row->contains.setText(rule.contains);row->ancestor.setText(rule.ancestor);row->tags.setText(rule.tags);row->contains.setTextToShowWhenEmpty("bass",juce::Colours::grey);row->ancestor.setTextToShowWhenEmpty("loop",juce::Colours::grey);row->tags.setTextToShowWhenEmpty("bass, synth",juce::Colours::grey);row->type.addItem("Keep type",1);for(int t:{0,1,2,4,5,6})row->type.addItem(LibraryStore::typeName(t),t+2);row->type.setSelectedId(rule.type<0?1:rule.type+2);row->remove.onClick=[this,ptr]{juce::MessageManager::callAsync([safe=juce::Component::SafePointer<ImportRulesPanel>(this),ptr]{if(!safe)return;auto& list=safe->rows;list.erase(std::remove_if(list.begin(),list.end(),[ptr](auto& r){return r.get()==ptr;}),list.end());safe->resized();});};rows.push_back(std::move(row));}
 void persist(){std::vector<ImportRule> rules;for(auto& r:rows)rules.push_back({r->contains.getText().trim(),r->ancestor.getText().trim(),r->tags.getText().trim(),r->type.getSelectedId()-2,r->enabled.getToggleState()});ImportRules::save(rules);}
 void resized()override{hint.setBounds(12,8,736,30);int y=44;for(auto& r:rows){r->enabled.setBounds(8,y,25,26);r->contains.setBounds(36,y,170,26);r->ancestor.setBounds(212,y,160,26);r->tags.setBounds(378,y,172,26);r->type.setBounds(556,y,150,26);r->remove.setBounds(712,y,32,26);y+=34;}add.setBounds(12,juce::jmax(y+8,getHeight()-42),100,28);save.setBounds(122,add.getY(),120,28);apply.setBounds(252,add.getY(),270,28);setSize(760,juce::jmax(400,y+50));}
};
